// 教案：DP 課 ②——兩層迴圈把一張表填滿
// 跟第 ① 課比只多一件事：格子從一列變成一張表，所以編號要兩個（列 i、行 w）。
// 這張表的大小（4 列 7 行）和第 ③ 課的背包表一模一樣，中間的公式故意寫得很笨。
#include <iostream>
#include <vector>

int main() {
    std::vector<std::vector<int>> table(4, std::vector<int>(7, 0));  //@ @tts [next] 我們開一張四列七行的表，每一格先填零 @layout sidebar:55 open:container close:locals
    for (int i = 1; i <= 3; ++i) {  //@ @tts [next] 外層迴圈一列一列往下走 | @2 [next] 這一列填完了，看還有沒有下一列 @layout sidebar:55 open:container
        for (int w = 0; w <= 6; ++w) {  //@ @guide 現在填第 {i} 列 @tts [next] 第 {i} 列，從最左邊那一行開始一行一行填 | @2 [next] 這一行填完了，看還有沒有下一行
            int value = i * 10 + w;  //@ @guide {table} @tts [next] 第 {i} 列第 {w} 行，算出來是 {i} 乘十再加 {w}
            table[i][w] = value;  //@ @guide {table[i][w]:lightblue} @tts [next] 把算出來的值寫進這一格 @layout pop:table:lightblue
        }
    }
    int corner = table[3][6];  //@ @guide {table[3][6]:orange} @tts [next] 表填滿了，我們把右下角那一格讀出來 @layout pop:table:orange
    std::cout << corner << "\n";  //@ @guide {table} @tts [next] 印出 {corner}，這就是右下角的值
    return 0;  //@ @tts [continue] 程式結束
}
